Rule.Source:
  import java.util.Map;
  import java.util.HashMap;

  import org.apache.log4j.Logger;

  import sailpoint.object.Filter;
  import sailpoint.object.Identity;
  import sailpoint.object.ProvisioningPlan;
  import sailpoint.object.ProvisioningPlan.AccountRequest;

  Logger logger = Logger.getLogger("iiq.alpha.Alpha-Rule-HRSoft-BeforeProvisioning");
  if (logger.isTraceEnabled()) {
    logger.trace("Entered to Alpha-Rule-HRSoft-BeforeProvisioning!!");
  }
  Identity identityObject = null;
  logger.debug("Plan : "+plan.toXml());
  if (plan != null) {
    List<AccountRequest> accReqList = plan.getAccountRequests(application.getName());
    AccountRequest accReq = accReqList.get(0);
    String nativeIdentity = accReq.getNativeIdentity();
    logger.debug("NativeIdentity from AccountRequest : "+nativeIdentity);
    identityObject = context.getUniqueObject(Identity.class, Filter.eq("employeeId",nativeIdentity));
    logger.debug("Identity Object : "+identityObject);

    if (identityObject != null) {
      logger.debug("Identity name : "+identityObject.getName());
      Map contextAttributeMap = new HashMap();
      contextAttributeMap.put("#plan.firstName#",identityObject.getFirstname());
      context.setProperty("contextAttributeMap",contextAttributeMap);
    }
  }
  if (identityObject != null) {
    logger.debug("Decaching the Identity Object");
    context.decache(identityObject);
  }
  if (logger.isTraceEnabled()) {
    logger.trace("Alpha-Rule-HRSoft-BeforeProvisioning Rule is Ended!!");
  }
